import random

# ---------- CHIP-8 reference interpreter ----------
class Chip8:
    FONT = [
        0xF0,0x90,0x90,0x90,0xF0, 0x20,0x60,0x20,0x20,0x70,
        0xF0,0x10,0xF0,0x80,0xF0, 0xF0,0x10,0xF0,0x10,0xF0,
        0x90,0x90,0xF0,0x10,0x10, 0xF0,0x80,0xF0,0x10,0xF0,
        0xF0,0x80,0xF0,0x90,0xF0, 0xF0,0x10,0x20,0x40,0x40,
        0xF0,0x90,0xF0,0x90,0xF0, 0xF0,0x90,0xF0,0x10,0xF0,
        0xF0,0x90,0xF0,0x90,0x90, 0xE0,0x90,0xE0,0x90,0xE0,
        0xE0,0x80,0x80,0x80,0xE0, 0xE0,0x90,0x90,0x90,0xE0,
        0xF0,0x80,0xF0,0x80,0xF0, 0xF0,0x80,0xF0,0x80,0x80,
    ]
    def __init__(self, rom, keys=None):
        self.mem = bytearray(4096)
        self.mem[0x050:0x050+80] = bytes(self.FONT)
        self.mem[0x200:0x200+len(rom)] = rom
        self.V = [0]*16
        self.I = 0; self.PC = 0x200
        self.stack = []
        self.g = [[0]*64 for _ in range(32)]
        self.dt = 0; self.st = 0
        self.keys = keys or {}
        self.halted = False
    def key(self, x): return 1 if self.keys.get(x) else 0
    def tick_timers(self):
        if self.dt > 0: self.dt -= 1
        self.st = self.dt if self.st > 0 else 0
    def step(self):
        if self.halted: return False
        hi = self.mem[self.PC]; lo = self.mem[self.PC+1]
        op = (hi<<8)|lo; self.PC = (self.PC+2) & 0xFFF
        n = hi; x = (hi>>4)&0xF; y = hi&0xF; kk = lo; addr = ((hi&0xF)<<8)|lo
        V = self.V
        if op == 0x00E0: self.g = [[0]*64 for _ in range(32)]
        elif op == 0x00EE:
            self.PC = self.stack.pop() if self.stack else self.PC
        elif n == 0x1: self.PC = addr
        elif n == 0x2: self.stack.append(self.PC); self.PC = addr
        elif n == 0x3:
            if V[x]==kk: self.PC=(self.PC+2)&0xFFF
        elif n == 0x4:
            if V[x]!=kk: self.PC=(self.PC+2)&0xFFF
        elif n == 0x5:
            if V[x]==V[y]: self.PC=(self.PC+2)&0xFFF
        elif n == 0x6: V[x]=kk
        elif n == 0x7: V[x]=(V[x]+kk)&0xFF
        elif n == 0x8:
            m = lo&0xF
            if m==0: V[x]=V[y]
            elif m==1: V[x]|=V[y]; V[0xF]=0
            elif m==2: V[x]&=V[y]; V[0xF]=0
            elif m==3: V[x]^=V[y]; V[0xF]=0
            elif m==4:
                s=V[x]+V[y]; V[x]=s&0xFF; V[0xF]=1 if s>255 else 0
            elif m==5:
                d=V[x]-V[y]; V[x]=d&0xFF; V[0xF]=1 if V[x]>=V[y] else 0
            elif m==6:
                lsb=V[x]&1; V[x]>>=1; V[0xF]=lsb
            elif m==7:
                d=V[y]-V[x]; V[x]=d&0xFF; V[0xF]=1 if V[x]>=V[x] and V[y]>=V[x] else 0
                # correct: borrow if V[y] < V[x] original
            elif m==0xE:
                msb=(V[x]>>7)&1; V[x]=(V[x]<<1)&0xFF; V[0xF]=msb
        elif n == 0x9:
            if V[x]!=V[y]: self.PC=(self.PC+2)&0xFFF
        elif n == 0xA: self.I=addr
        elif n == 0xB: self.PC=(addr+V[0])&0xFFF
        elif n == 0xC: V[x]=(random.randint(0,255)&kk)
        elif n == 0xD:
            sx=V[x]%64; sy=V[y]%32; h=lo&0xF; coll=0
            for row in range(h):
                byte=self.mem[(self.I+row)&0xFFF]
                for b in range(8):
                    if (byte>>(7-b))&1:
                        px=(sx+b)%64; py=(sy+row)%32
                        if self.g[py][px]: coll=1
                        self.g[py][px]^=1
            V[0xF]=coll
        elif n == 0xE:
            if kk==0x9E:
                if self.key(V[x]): self.PC=(self.PC+2)&0xFFF
            elif kk==0xA1:
                if not self.key(V[x]): self.PC=(self.PC+2)&0xFFF
        elif n == 0xF:
            if kk==0x07: V[x]=self.dt
            elif kk==0x0A:
                for k in range(16):
                    if self.key(k): V[x]=k; break
                else: self.PC=(self.PC-2)&0xFFF
            elif kk==0x15: self.dt=V[x]
            elif kk==0x18: self.st=V[x]
            elif kk==0x1E: self.I=(self.I+V[x])&0xFFF
            elif kk==0x29: self.I=V[x]*5
            elif kk==0x33:
                v=V[x]; self.mem[self.I]=v//100; self.mem[self.I+1]=(v//10)%10; self.mem[self.I+2]=v%10
            elif kk==0x55:
                for i in range(x+1): self.mem[(self.I+i)&0xFFF]=V[i]
            elif kk==0x65:
                for i in range(x+1): V[i]=self.mem[(self.I+i)&0xFFF]
        else:
            raise ValueError(f"unknown op {op:#06x} at {self.PC-2:#05x}")
        self.tick_timers()
        return True

print("reference interpreter defined")
