import re, json

# ---------------- tiny CHIP-8 assembler ----------------
LABELS = {}
class AsmError(Exception): pass

def num(tok, pc):
    tok = tok.strip()
    if tok.startswith('0x') or tok.startswith('0X'): return int(tok,16)
    if re.fullmatch(r'\d+', tok): return int(tok)
    if tok in LABELS: return LABELS[tok]
    raise AsmError(f'unknown token {tok!r} at {pc:#05x}')

def assemble(src, origin=0x200):
    lines = [l.split(';')[0].strip() for l in src.splitlines()]
    lines = [l for l in lines if l]
    # pass 1: labels
    pc = origin
    for l in lines:
        m = re.match(r'^([A-Za-z_][\w]*)\s*:\s*(.*)$', l)
        if m:
            if m.group(1) in LABELS: raise AsmError('dup label '+m.group(1))
            LABELS[m.group(1)] = pc
            l = m.group(2).strip()
            if not l: continue
        pc += 2
    # pass 2
    pc = origin; out = []
    for l in lines:
        m = re.match(r'^([A-Za-z_][\w]*)\s*:\s*(.*)$', l)
        if m: l = m.group(2).strip()
        if not l: continue
        words = re.split(r'[\s,]+', l)
        mn = words[0].upper(); a = words[1:]
        def N(i): return num(a[i], pc)
        def reg(i):
            t = a[i].upper()
            m2 = re.fullmatch(r'V([0-9A-F])', t)
            if not m2: raise AsmError(f'expected Vx, got {t!r} at {pc:#05x}')
            return int(m2.group(1),16)
        op = None
        if mn=='CLS': op = 0x00E0
        elif mn=='RET': op = 0x00EE
        elif mn=='JP':
            if a[0].upper()=='V0': op = 0xB00 | (num(a[1],pc) & 0xFFF)
            else: op = 0x100 | (N(0) & 0xFFF)
        elif mn=='CALL': op = 0x200 | (N(0) & 0xFFF)
        elif mn=='SE':
            if a[1].upper().startswith('V'):
                if len(a)>2 and a[2].upper().startswith('V'): op = 0x5000|reg(0)<<8|reg(1)<<4
                else: raise AsmError('se')
            else: op = 0x3000|reg(0)<<8|(N(1)&0xFF)
        elif mn=='SNE':
            if a[1].upper().startswith('V'): op = 0x9000|reg(0)<<8|reg(1)<<4
            else: op = 0x4000|reg(0)<<8|(N(1)&0xFF)
        elif mn=='LD':
            if a[0].upper().startswith('V'):
                if a[1].upper()=='F':   op = 0xF000|reg(0)<<8|0x65
                elif a[1].upper()=='DT':op = 0xF000|reg(0)<<8|0x07
                elif a[1].upper()=='K': op = 0xF000|reg(0)<<8|0x0A
                elif a[1].upper().startswith('V'): op = 0x8000|reg(0)<<8|reg(1)<<4
                elif a[1]=='[':         op = 0xF000|reg(0)<<8|0x33   # LD Vx, [I]  (BCD)
                else: op = 0x6000|reg(0)<<8|(N(1)&0xFF)
            elif a[0]=='[':             op = 0xF000|reg(1)<<8|0x55   # LD [I], Vx
            else: op = 0xA000|(N(0)&0xFFF)                            # LD F, addr -> I
        elif mn=='ADD':
            if a[0].upper()=='F': op = 0xF000|(N(1)&0xFFF)            # ADD F, addr
            elif a[1].upper().startswith('V'): op = 0x8000|reg(0)<<8|reg(1)<<4|0x4
            elif a[1]=='I': op = 0xF000|reg(0)<<8|0x1E
            else: op = 0x7000|reg(0)<<8|(N(1)&0xFF)
        elif mn=='AND': op = 0x8000|reg(0)<<8|reg(1)<<4|0x2
        elif mn=='OR':  op = 0x8000|reg(0)<<8|reg(1)<<4|0x1
        elif mn=='XOR': op = 0x8000|reg(0)<<8|reg(1)<<4|0x3
        elif mn=='SUB': op = 0x8000|reg(0)<<8|reg(1)<<4|0x5
        elif mn=='SHR': op = 0x8000|reg(0)<<8|reg(1)<<4|0x6
        elif mn=='SUBN':op = 0x8000|reg(0)<<8|reg(1)<<4|0x7
        elif mn=='SHL': op = 0x8000|reg(0)<<8|reg(1)<<4|0xE
        elif mn=='SKNP':op = 0xE000|reg(0)<<8|0xA1
        elif mn=='SKP': op = 0xE000|reg(0)<<8|0x9E
        elif mn=='DRW': op = 0xD000|reg(0)<<8|reg(1)<<4|(N(2)&0xF)
        elif mn=='RND': op = 0xC000|reg(0)<<8|(N(1)&0xFF)
        elif mn=='DT':  op = 0xF000|reg(0)<<8|0x15
        elif mn=='ST':  op = 0xF000|reg(0)<<8|0x18
        else: raise AsmError(f'unknown mnemonic {mn} at {pc:#05x}')
        out.append((op>>8)&0xFF); out.append(op&0xFF)
        pc += 2
    return bytes(out)

print('assembler ok')
